import sys

def solve():
    lines = sys.stdin.read().split()
    if not lines: return
    n = int(lines[0])
    nums = [int(x) for x in lines[1:n+1]]
    target = int(lines[n+1])

    lookup = {}
    for i, x in enumerate(nums):
        diff = target - x
        if diff in lookup:
            print(f"{lookup[diff]} {i}")
            return
        lookup[x] = i

if __name__ == '__main__':
    solve()

