#include <vector>
#include <unordered_map>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> nums(n);
    for(int i = 0; i < n; i++) cin >> nums[i];
    int target;
    cin >> target;

    unordered_map<int, int> lookup;
    for(int i = 0; i < n; i++) {
        int diff = target - nums[i];
        if (lookup.count(diff)) {
            cout << lookup[diff] << " " << i << endl;
            return 0;
        }
        lookup[nums[i]] = i;
    }
    return 0;
}

