using namespace std;

int main() {
    string s, filtered = "";
    if (getline(cin, s)) {
        for(char c : s) if (isalnum(c)) filtered += tolower(c);
        int l = 0, r = filtered.size() - 1;
        bool pal = true;
        while(l < r) {
            if (filtered[l++] != filtered[r--]) { pal = false; break; }
        }
        cout << (pal ? "YES" : "NO") << endl;
    }
    return 0;
}

