#include <ctype.h>
#include <string.h>

int main() {
    char s[10000];
    if (fgets(s, sizeof(s), stdin)) {
        char clean[10000];
        int idx = 0;
        for(int i = 0; s[i]; i++) {
            if (isalnum((unsigned char)s[i])) clean[idx++] = tolower((unsigned char)s[i]);
        }
        int l = 0, r = idx - 1, pal = 1;
        while(l < r) {
            if (clean[l++] != clean[r--]) { pal = 0; break; }
        }
        printf("%s\n", pal ? "YES" : "NO");
    }
    return 0;
}
